const execucao = $json.execution || {};
const fluxo = $json.workflow || {};
const erro = execucao.error || $json.trigger?.error || {};
const quando = new Date().toLocaleString('pt-BR', { timeZone: 'America/Recife' });
const linhas = [
  `Fluxo: ${fluxo.name || fluxo.id || 'desconhecido'}`,
  `Quando: ${quando}`,
  `Etapa que falhou: ${execucao.lastNodeExecuted || 'n/d'}`,
  `Erro: ${erro.message || 'sem mensagem'}`,
  execucao.url ? `Execução: ${execucao.url}` : 'Execução: n/d',
  '',
  'Leads com falha ficam na tabela leads_pendentes e são reprocessados pela conciliação de hora em hora.'
];
return { json: { assunto: `[n8n] Falha em ${fluxo.name || 'fluxo'}`, texto: linhas.join('\n') } };
